/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::ELECTION_UNKNOWN,
    error_codes::NOT_OPEN,
    error_codes::MANIFEST_MISMATCH,
    error_codes::NOT_ELIGIBLE,
    error_codes::ALREADY_ISSUED,
    error_codes::REQUEST_INVALID,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `vtc/elections/tickets/issue:electionUnknown`
    ///
    /// No registered election with this identifier exists for this community, or the signer may not see it (CONVENTIONS §7). Answered identically, so the task is no existence oracle.
    ///
    /// Declared `retryable: false`.
    pub const ELECTION_UNKNOWN: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/elections/tickets/issue:electionUnknown",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vtc/elections/tickets/issue:notOpen`
    ///
    /// Tickets are not being issued for the election: registration has not opened, voting has closed, the election is being closed or was cancelled, or the ballot box has not yet registered it (VTI-VOT-024).
    ///
    /// Declared `retryable: false`.
    pub const NOT_OPEN: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/elections/tickets/issue:notOpen",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vtc/elections/tickets/issue:manifestMismatch`
    ///
    /// `manifestDigest` is not the digest of the election's registered manifest. The requester read another manifest than the one the election runs under.
    ///
    /// Declared `retryable: false`.
    pub const MANIFEST_MISMATCH: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/elections/tickets/issue:manifestMismatch",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vtc/elections/tickets/issue:notEligible`
    ///
    /// The election's roll rule does not admit the signer as the community's records stand now (VTI-VOT-021).
    ///
    /// Declared `retryable: false`.
    pub const NOT_ELIGIBLE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/elections/tickets/issue:notEligible",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vtc/elections/tickets/issue:alreadyIssued`
    ///
    /// The community has already issued the signer a ticket for this election, in answer to a different request (VTI-VOT-022). A resend of the request it answered is answered with that answer, never with this code.
    ///
    /// Declared `retryable: false`.
    pub const ALREADY_ISSUED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/elections/tickets/issue:alreadyIssued",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vtc/elections/tickets/issue:requestInvalid`
    ///
    /// `request.label` is not `voter/<electionId>` for this election, or the blinded request does not verify under the community's voting parameters.
    ///
    /// Declared `retryable: false`.
    pub const REQUEST_INVALID: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/elections/tickets/issue:requestInvalid",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
}
